package com.buildertoolbox.mixin;import net.minecraft.client.Mouse;import net.minecraft.client.input.MouseInput;import org.spongepowered.asm.mixin.Mixin;import org.spongepowered.asm.mixin.injection.*;import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;@Mixin(Mouse.class)public abstract class MouseMixin {@Inject(method="onMouseButton",at=@At("HEAD"),cancellable=true)private void tools$mouse(long window,MouseInput input,int action,CallbackInfo ci){if(com.buildertoolbox.client.ClientRuntime.EVENT_BUS.post(new com.buildertoolbox.client.events.meteor.MouseClickEvent(input.button(),action)).isCancelled())ci.cancel();}}